"use client";

import { useCallback, useState } from "react";
import { motion } from "framer-motion";
import {
  ChartFrame,
  formatCompact,
  type AxisSpec,
  type ChartContext,
  type ChartPoint,
  type SeriesSpec,
} from "@/components/ui/ChartFrame";

/* ------------------------------------------------------------------ *
 * Geometry
 * ------------------------------------------------------------------ */

export type BarLayout = "grouped" | "stacked" | "diverging";

/**
 * A bar rounded only at the end it grows towards.
 *
 * Rounding all four corners looks fine on a single bar and wrong the
 * moment bars are stacked: every segment boundary picks up a pair of
 * notches and the stack reads as a column of separate pills rather than
 * one quantity divided up. The far end is the end the eye measures, so
 * that is the end that gets the radius.
 */
export function barPath(
  x: number,
  y: number,
  w: number,
  h: number,
  radius: number,
  side: "top" | "bottom" | "right" | "left",
): string {
  const vertical = side === "top" || side === "bottom";
  const r = Math.max(0, Math.min(radius, vertical ? Math.min(w / 2, h) : Math.min(h / 2, w)));
  if (r <= 0.5) return `M${x},${y} h${w} v${h} h${-w} Z`;
  const s = (n: number) => Math.round(n * 100) / 100;
  switch (side) {
    case "top":
      return `M${s(x)},${s(y + h)} V${s(y + r)} a${s(r)},${s(r)} 0 0 1 ${s(r)},${s(-r)} h${s(w - 2 * r)} a${s(r)},${s(r)} 0 0 1 ${s(r)},${s(r)} V${s(y + h)} Z`;
    case "bottom":
      return `M${s(x)},${s(y)} V${s(y + h - r)} a${s(r)},${s(r)} 0 0 0 ${s(r)},${s(r)} h${s(w - 2 * r)} a${s(r)},${s(r)} 0 0 0 ${s(r)},${s(-r)} V${s(y)} Z`;
    case "right":
      return `M${s(x)},${s(y)} H${s(x + w - r)} a${s(r)},${s(r)} 0 0 1 ${s(r)},${s(r)} v${s(h - 2 * r)} a${s(r)},${s(r)} 0 0 1 ${s(-r)},${s(r)} H${s(x)} Z`;
    default:
      return `M${s(x + w)},${s(y)} H${s(x + r)} a${s(r)},${s(r)} 0 0 0 ${s(-r)},${s(r)} v${s(h - 2 * r)} a${s(r)},${s(r)} 0 0 0 ${s(r)},${s(r)} H${s(x + w)} Z`;
  }
}

/** Signed value for a series, with the diverging side already applied. */
function signed(v: number, id: string, layout: BarLayout, negative: string[]): number {
  return layout === "diverging" && negative.includes(id) ? -Math.abs(v) : v;
}

function extentFor(
  points: ChartPoint[],
  ids: string[],
  layout: BarLayout,
  negative: string[],
): [number, number] {
  let lo = 0;
  let hi = 0;
  for (const p of points) {
    let up = 0;
    let down = 0;
    for (const id of ids) {
      const raw = p.values[id];
      if (typeof raw !== "number" || !Number.isFinite(raw)) continue;
      const v = signed(raw, id, layout, negative);
      if (layout === "grouped") {
        lo = Math.min(lo, v);
        hi = Math.max(hi, v);
      } else if (v < 0) down += v;
      else up += v;
    }
    if (layout !== "grouped") {
      lo = Math.min(lo, down);
      hi = Math.max(hi, up);
    }
  }
  return [lo, hi];
}

/* ------------------------------------------------------------------ *
 * Component
 * ------------------------------------------------------------------ */

export interface BarChartProps {
  data: ChartPoint[];
  series: SeriesSpec[];
  label: string;
  summary?: string;
  layout?: BarLayout;
  /** `vertical` is a column chart; `horizontal` is a bar chart. */
  orientation?: "vertical" | "horizontal";
  /**
   * Diverging only: the series drawn on the far side of the baseline.
   * Values stay positive in the data and are negated here, so a caller
   * never has to store a sign that only exists for the drawing.
   *
   * Segments stack outward from the baseline in `series` order, so the
   * first series listed sits against zero and the last is furthest out.
   * On a sentiment scale that ordering is the reading: put the mildest
   * category nearest the baseline and the strongest at the ends.
   */
  negative?: string[];
  /** Names for the two sides of a diverging baseline, e.g. ["Against", "For"]. */
  directions?: [string, string];
  /** Share of each band left as gutter between categories. */
  bandPad?: number;
  radius?: number;
  x?: AxisSpec;
  y?: AxisSpec;
  height?: number;
  legend?: boolean;
  formatValue?: (v: number) => string;
  className?: string;
}

export function BarChart({
  data,
  series,
  label,
  summary,
  layout = "grouped",
  orientation = "vertical",
  negative = [],
  directions,
  bandPad = 0.28,
  radius = 4,
  x,
  y,
  height = 280,
  legend = true,
  formatValue,
  className,
}: BarChartProps) {
  const horizontal = orientation === "horizontal";
  const categories = data.map((p) => String(p.x));

  const yExtent = useCallback(
    (ids: string[], points: ChartPoint[]) => extentFor(points, ids, layout, negative),
    [layout, negative],
  );

  const draw = (ctx: ChartContext) => {
    const base = ctx.value.at(0);
    const thickness = ctx.position.band * (1 - bandPad);
    const ids = ctx.series.map((s) => s.id);
    // Grouped bars split the band; stacked and diverging share it.
    const slot = layout === "grouped" ? thickness / Math.max(1, ids.length) : thickness;
    const inner = layout === "grouped" ? Math.max(1, slot - 2) : slot;

    return (
      <>
        {ctx.points.map((p, i) => {
          const centre = ctx.px(p, i);
          const start = centre - thickness / 2;

          // Stacked and diverging accumulate from the baseline outwards, in
          // both directions independently, so a diverging stack grows away
          // from zero on each side rather than through it.
          let up = 0;
          let down = 0;

          // Which segment ends up furthest from the baseline has to be known
          // before the stack is walked, not discovered while walking it.
          let lastUp = -1;
          let lastDown = -1;
          ctx.series.forEach((s, si) => {
            const raw = p.values[s.id];
            if (typeof raw !== "number" || !Number.isFinite(raw)) return;
            if (signed(raw, s.id, layout, negative) < 0) lastDown = si;
            else lastUp = si;
          });

          const bars = ctx.series.map((s, si) => {
            const raw = p.values[s.id];
            if (typeof raw !== "number" || !Number.isFinite(raw)) return null;
            const v = signed(raw, s.id, layout, negative);

            let from: number;
            let to: number;
            if (layout === "grouped") {
              from = 0;
              to = v;
            } else if (v < 0) {
              from = down;
              to = down + v;
              down = to;
            } else {
              from = up;
              to = up + v;
              up = to;
            }

            const a = ctx.value.at(from);
            const b = ctx.value.at(to);
            const lo = Math.min(a, b);
            const span = Math.abs(b - a);
            if (span < 0.01) return null;

            const off = layout === "grouped" ? start + si * slot + (slot - inner) / 2 : start;
            // Only the segment furthest from the baseline is rounded, so a
            // stack reads as one divided quantity.
            const outermost = layout === "grouped" || si === (v < 0 ? lastDown : lastUp);
            const side = horizontal ? (v < 0 ? "left" : "right") : v < 0 ? "bottom" : "top";
            const d = horizontal
              ? barPath(lo, off, span, inner, outermost ? radius : 0, side)
              : barPath(off, lo, inner, span, outermost ? radius : 0, side);

            const origin = horizontal ? (v < 0 ? "right" : "left") : v < 0 ? "top" : "bottom";
            const grow = horizontal ? { scaleX: 1 } : { scaleY: 1 };
            const seed = horizontal ? { scaleX: 0 } : { scaleY: 0 };

            const shape = (
              <path
                d={d}
                fill={ctx.paint(s.id)}
                stroke={ctx.dash(s.id) ? "var(--cf-dot-ring)" : undefined}
                strokeDasharray={ctx.dash(s.id)}
                strokeWidth={ctx.dash(s.id) ? 1.5 : undefined}
              />
            );

            // Diverging bars start on opposite sides of the baseline, so
            // each one has to grow from its own edge. Grouped and stacked
            // bars all sit on the same side, so the whole category can
            // scale as one object instead.
            return layout === "diverging" ? (
              <motion.g
                key={s.id}
                style={{ transformBox: "fill-box", transformOrigin: origin }}
                initial={ctx.reduceMotion ? false : seed}
                animate={ctx.inView ? grow : undefined}
                transition={{ duration: 0.6, delay: 0.05 + i * 0.03, ease: [0.22, 1, 0.36, 1] }}
              >
                {shape}
              </motion.g>
            ) : (
              <g key={s.id}>{shape}</g>
            );
          });

          if (layout === "diverging") return <g key={`bar-${i}`}>{bars}</g>;

          return (
            <motion.g
              key={`bar-${i}`}
              style={{
                transformBox: "fill-box",
                transformOrigin: horizontal ? "left" : "bottom",
              }}
              initial={ctx.reduceMotion ? false : horizontal ? { scaleX: 0 } : { scaleY: 0 }}
              animate={ctx.inView ? (horizontal ? { scaleX: 1 } : { scaleY: 1 }) : undefined}
              transition={{ duration: 0.6, delay: 0.05 + i * 0.04, ease: [0.22, 1, 0.36, 1] }}
            >
              {bars}
            </motion.g>
          );
        })}

        {/* The baseline is the thing every bar is measured from, so it is
            drawn over the bars rather than under them. */}
        {layout === "diverging" && (
          <line
            x1={horizontal ? base : 0}
            x2={horizontal ? base : ctx.width}
            y1={horizontal ? 0 : base}
            y2={horizontal ? ctx.height : base}
            stroke="var(--cf-axis)"
            strokeWidth={1}
          />
        )}
      </>
    );
  };

  // A diverging axis is labelled with magnitudes. The side of the baseline
  // already carries the direction, and a column of minus signs would say
  // that half the readings are negative quantities, which they are not.
  const valueFormat = layout === "diverging" ? (v: number) => formatCompact(Math.abs(v)) : undefined;
  const posSpec: AxisSpec = { categories, ...(horizontal ? y : x) };
  const valSpec: AxisSpec = { zero: true, format: valueFormat, ...(horizontal ? x : y) };

  return (
    <div className={className}>
      <ChartFrame
        label={label}
        summary={summary}
        series={series}
        points={data}
        height={height}
        legend={legend}
        orientation={orientation}
        formatValue={formatValue}
        yExtent={yExtent}
        x={horizontal ? valSpec : posSpec}
        y={horizontal ? posSpec : valSpec}
      >
        {draw}
      </ChartFrame>

      {layout === "diverging" && directions && (
        <p className="mt-2 flex items-center justify-between text-xs text-stone-500">
          <span>{directions[0]}</span>
          <span>{directions[1]}</span>
        </p>
      )}
    </div>
  );
}
